// ---------------------------------------------------------------------------
// The slow, obvious reference. Nothing here imports from src/calendar.ts.
// ---------------------------------------------------------------------------

const fmtCache = new Map<string, Intl.DateTimeFormat>();
const fmt = (tz: string) => {
  let f = fmtCache.get(tz);
  if (f === undefined) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
    fmtCache.set(tz, f);
  }
  return f;
};

function slowParts(tz: string, ms: number): CivilDateTime {
  const o: Record<string, string> = {};
  for (const p of fmt(tz).formatToParts(ms)) if (p.type !== 'literal') o[p.type] = p.value;
  return {
    year: Number(o['year']),
    month: Number(o['month']),
    day: Number(o['day']),
    hour: Number(o['hour']) % 24,
    minute: Number(o['minute']),
    second: Number(o['second']),
  };
}

const sameCivil = (a: CivilDateTime, b: CivilDateTime) =>
  a.year === b.year &&
  a.month === b.month &&
  a.day === b.day &&
  a.hour === b.hour &&
  a.minute === b.minute;

/**
 * Every instant whose local time in `tz` is `civil`, found by trying EVERY
 * OFFSET.
 *
 * -14:00 to +14:00 in fifteen-minute steps — 113 candidates — each turned into
 * an instant and formatted back, keeping the ones that match. That is the whole
 * space of UTC offsets the IANA database uses in the modern era, so it cannot
 * miss a candidate; and unlike the ±24-hour probe in `calendar.ts` it makes no
 * assumption about WHICH offsets are plausible, which is exactly the assumption
 * that loses the second instant of an autumn fold.
 *
 * (The first draft scanned four days in one-minute steps. It is even more
 * obviously exhaustive and it took over ten minutes to build the file, which is
 * a reference nobody would run.)
 */
const OFFSET_STEPS = (() => {
  const out: number[] = [];
  for (let m = -14 * 60; m <= 14 * 60; m += 15) out.push(m * 60_000);
  return out;
})();

function slowCandidates(tz: string, civil: CivilDateTime): number[] {
  const wall = Date.UTC(civil.year, civil.month - 1, civil.day, civil.hour, civil.minute, 0);
  const out: number[] = [];
  for (const offset of OFFSET_STEPS) {
    const t = wall - offset;
    if (sameCivil(slowParts(tz, t), civil) && !out.includes(t)) out.push(t);
  }
  return out.sort((a, b) => a - b);
}

/** Civil date + N days, by stepping and re-reading. Never a day number. */
function slowAddDays(tz: string, civil: CivilDateTime, days: number): CivilDateTime {
  let cur = civil;
  const step = days >= 0 ? 1 : -1;
  for (let i = 0; i !== days; i += step) {
    // Noon is safe from every DST transition on earth, so stepping through it
    // cannot skip or repeat a civil date.
    const noon = slowCandidates(tz, { ...cur, hour: 12, minute: 0, second: 0 })[0]!;
    const next = slowParts(tz, noon + step * 86_400_000);
    cur = { ...cur, year: next.year, month: next.month, day: next.day };
  }
  return cur;
}

const iso = (ms: number) => new Date(ms).toISOString();

