/**
 * The wide rule set — every selector exercised, plus the three ways a rule can be
 * out of force.
 *
 * `RULES` above is six narrative cases a person can read. This one exists to be
 * SWEPT: 64 contexts × 3 instants against it enumerates the whole decision surface
 * of `resolveCirculationPolicy`, which is what phase 77's Rust core has to
 * reproduce. Six hand-written cases would let a Rust resolver that ignored
 * `shelvingLocationId` entirely pass the vector file.
 */
const WIDE_RULES = [
  rule('w-0-default', 'Library default', {}),
  rule('w-1-pickup', 'Pickup at B', { pickupBranchId: 'br-b' }),
  rule('w-2-checkout', 'Checked out at B', { checkoutBranchId: 'br-b' }),
  rule('w-3-shelf', 'Reference shelf', { shelvingLocationId: 'loc-ref' }),
  rule('w-4-owning', 'Owned by B', { owningBranchId: 'br-b' }),
  rule('w-5-type', 'DVDs', { itemTypeId: 'it-dvd' }),
  rule('w-6-cat', 'Children', { patronCategoryId: 'cat-child' }),
  rule('w-7-cat-type', 'Children + DVDs', {
    patronCategoryId: 'cat-child',
    itemTypeId: 'it-dvd',
  }),
  rule('w-8-shelf-checkout', 'Reference, checked out at B', {
    shelvingLocationId: 'loc-ref',
    checkoutBranchId: 'br-b',
  }),
  rule('w-9-all', 'Every selector', {
    patronCategoryId: 'cat-child',
    itemTypeId: 'it-dvd',
    owningBranchId: 'br-b',
    shelvingLocationId: 'loc-ref',
    checkoutBranchId: 'br-b',
    pickupBranchId: 'br-b',
  }),
  // Priority is the escape hatch: less specific, and it still wins — but only
  // while it is in force. Without the window it shadows `w-9-all` at every
  // instant, and the top of the specificity lattice becomes a rule that can never
  // win, so a Rust resolver that got 63 wrong would pass the sweep.
  rule('w-a-priority', 'Spring override', { pickupBranchId: 'br-b' }, 50, {
    effectiveTo: '2026-06-01T00:00:00Z',
  }),
  // In force only for the middle instant of the three the sweep uses.
  rule('w-b-window', 'Term-time rule', { patronCategoryId: 'cat-child' }, 200, {
    effectiveFrom: '2026-05-01T00:00:00Z',
    effectiveTo: '2026-06-01T00:00:00Z',
  }),
  // Never in force. A resolver that ignored `enabled` would return it everywhere,
  // because its priority beats everything.
  rule('w-c-disabled', 'Disabled', {}, 999, { enabled: false }),
];

