/**
 * The sweep snapshot. Same policy tables, the wide rule set, a different version
 * number so a vector that read the wrong snapshot fails loudly rather than
 * coincidentally passing.
 */
const SNAP_2 = { ...snapshots['snap-1'], version: 9, rules: WIDE_RULES };
(snapshots as Record<string, unknown>)['snap-2'] = SNAP_2;

// ---------------------------------------------------------------------------
// Vectors
// ---------------------------------------------------------------------------

const vectors: Record<string, unknown>[] = [];

// 1. RANK — all 64 selector combinations. The expectation is BIT SHIFTS, not the
//    named-weight table `rank.ts` uses.
for (let n = 0; n < 64; n += 1) {
  const selectors: Record<string, string | null> = {};
  SELECTORS.forEach((name, i) => {
    selectors[name] = (n >> (5 - i)) & 1 ? `x-${name}` : null;
  });
  vectors.push({
    kind: 'rank',
    id: `rank-${String(n).padStart(2, '0')}`,
    selectors,
    expectSpecificity: n,
  });
}

// 2. CIVIL — every wall-clock minute across both Athens DST transitions, plus a
//    sweep of ordinary days. Expectations from the linear scan.
const civilCases: { civil: CivilDateTime; note: string }[] = [];
for (let m = 0; m < 6 * 60; m += 15) {
  civilCases.push({
    civil: { year: 2026, month: 3, day: 29, hour: Math.floor(m / 60), minute: m % 60, second: 0 },
    note: 'spring forward',
  });
  civilCases.push({
    civil: { year: 2026, month: 10, day: 25, hour: Math.floor(m / 60), minute: m % 60, second: 0 },
    note: 'autumn back',
  });
}
// One date in every month, at four times of day: the offset is +02:00 for five
// of them and +03:00 for seven, and the boundary months are where an
// implementation that hard-coded either would be caught.
for (let month = 1; month <= 12; month += 1) {
  for (const hour of [0, 6, 12, 23]) {
    civilCases.push({
      civil: { year: 2026, month, day: 15, hour, minute: 30, second: 0 },
      note: 'monthly sweep',
    });
  }
}
// Midnight and the last minute of a day, on both sides of both transitions —
// the places an off-by-one in the hour reading shows up as an off-by-one DAY.
for (const [month, day] of [
  [3, 28],
  [3, 30],
  [10, 24],
  [10, 26],
  [12, 31],
] as const) {
  for (const [hour, minute] of [
    [0, 0],
    [23, 59],
  ] as const) {
    civilCases.push({
      civil: { year: 2026, month, day, hour, minute, second: 0 },
      note: 'day edge',
    });
  }
}
for (const [i, c] of civilCases.entries()) {
  const found = slowCandidates(TZ, c.civil);
  for (const dis of ['earlier', 'later'] as const) {
    const kind = found.length === 0 ? 'gap' : found.length === 1 ? 'unique' : 'ambiguous';
    // For a gap the reference has no instant to offer, so the vector records
    // only the KIND. The package's answer for a gap is an engineering choice
    // (the instant either side), not something a scan can discover.
    if (kind === 'gap') {
      vectors.push({
        kind: 'civil',
        id: `civil-${i}-${dis}`,
        timezone: TZ,
        civil: c.civil,
        disambiguation: dis,
        expectInstant: null,
        expectKind: 'gap',
      });
      continue;
    }
    const pick = dis === 'later' ? found[found.length - 1]! : found[0]!;
    vectors.push({
      kind: 'civil',
      id: `civil-${i}-${dis}`,
      timezone: TZ,
      civil: c.civil,
      disambiguation: dis,
      expectInstant: iso(pick),
      expectKind: kind,
    });
  }
}

